# -*- coding: utf-8 -*-
"""فصل ۱ (مقدمه) و فصل ۲ (زندگی)."""

def ch1(D):
    D.h1("مقدمه: چرا مک‌لوهان و چرا اکنون؟", num="۱")

    D.h2("۱.۱. مردی که قرن بیستم را در اندیشیدن به رسانه دگرگون کرد")
    D.para("هیچ اندیشمند دیگری در قرن بیستم، به اندازه‌ی هربرت مارشال مک‌لوهان (1911–1980) بر شیوه‌ی اندیشیدن مدرن به فناوری، رسانه و فرهنگ اثر نگذاشته است. اگر امروز روزانه در شبکه‌های اجتماعی «دهکده‌ی جهانی»ای زندگی می‌کنیم که در آن همه‌چیز هم‌زمان می‌شود، اگر می‌دانیم که اثر گوشی هوشمند بر ما فراتر از محتوایی است که در آن می‌خوانیم، اگر از «رسانه‌های گرم و سرد» در تحلیل تلویزیون و رادیو و پادکست سخن می‌گوییم، وامدار اندیشه‌ای‌ایم که بیش از شصت سال پیش شکل گرفت. مک‌لوهان با دو شعار — «رسانه پیام است» (the medium is the message) و «دهکده‌ی جهانی» (global village) — زبان روزمره‌ی تحلیل رسانه را ساخت.")
    D.para("اما آنچه این سند را از یک «معرفی سطحی» جدا می‌کند، این است که می‌خواهد شما را نه به عنوان مخاطبِ چند شعار، بلکه به عنوان یک «مک‌لوهان‌شناس» — کسی که آثار اصلی را از زبان خودِ مک‌لوهان بخواند، نقدها را بشناسد و می‌داند کجاها این اندیشه قوی و کجاها آسیب‌پذیر است — هدایت کند.")

    D.h2("۱.۲. سه ستون مک‌لوهان‌شناسی حرفه‌ای")
    D.para("مک‌لوهان‌شناسیِ تخصصی بر سه ستون استوار است و این سند نیز همین سه ستون را، به ترتیب، می‌سازد:")
    D.bullet("ستون اول: زندگی و شخصیت — چه کسی بود، در چه محیطی، تحت تأثیر چه کسانی. نمی‌توان آثار مک‌لوهان را فهمید بدون فهم ریشه‌ی ادبی او، ایمان کاتولیکش، و رابطه‌ی استاد-شاگردی او با هارولد اینیس.")
    D.bullet("ستون دوم: آثار اصلی — کتاب‌ها و مقالات خودِ او. این‌ها منابع دست اول (primary sources) هستند و باید به ترتیب و با دقت خوانده شوند.")
    D.bullet("ستون سوم: نقد و تحلیل — آنچه دیگران درباره‌ی او نوشته‌اند (منابع دست دوم). این ستون به شما نشان می‌دهد کجاها اندیشه‌ی او چالش‌پذیر بوده و چگونه در دهه‌های اخیر بازخوانی شده است.")

    D.h2("۱.۳. چگونه از این سند استفاده کنید")
    D.para("این سند ۱۲ فصل دارد. فصل‌های ۲ تا ۴ (زندگی، تحصیلات، زمینه‌ی فکری) بنیان را می‌سازند. فصل‌های ۵ تا ۸، شش مفهوم نظریه‌ای محوری را، یکی‌یکی و با منابع اصلی، بازشمی‌کنند. فصل ۹، قفسه‌ی کتاب‌های مک‌لوهان را به ترتیب خواندنی معرفی می‌کند. فصل ۱۰، مقالات و مصاحبه‌های کلیدی — از جمله مصاحبه‌ی پُرجزئیات Playboy (1969) — را مرور می‌کند. فصل ۱۱، نقدها و چالش‌ها را — از روش‌شناسی تا نژاد و پسااستعماری — بررسی می‌کند. و فصل ۱۲، میراث او را تا عصر دیجیتال، هوش مصنوعی و «دهکده‌ی جهانی‌»ای که امروز در آن زندگی می‌کنیم، پی می‌گیرد.")
    D.callout("نکته‌ی روش‌شناختی:", "در پایان هر فصل نظریه‌ای، یک «تمرین کاربردی» آورده‌ام که مفهوم را روی یک رسانه‌ی معاصر (اینترنت، گوشی، هوش مصنوعی) به‌کار می‌بندید. این تمرین‌ها همان ابزاری‌اند که یک رسانه‌شناس حرفه‌ای هر روز به کار می‌گیرد.")
    D.page_break()


def ch2(D):
    D.h1("زندگی: از ادمونتون تا تورنتو", num="۲")

    D.h2("۲.۱. نگاهی کلی به زندگی")
    D.table(
        headers=["مورد", "جزئیات"],
        rows=[
            ["نام کامل", "هربرت مارشال مک‌لوهان (Herbert Marshall McLuhan)"],
            ["تولد", "۲۱ ژوئیه ۱۹۱۱ — ادمونتون، آلبرتا، کانادا"],
            ["درگذشت", "۳۱ دسامبر ۱۹۸۰ — تورنتو، انتاریو (۶۹ ساله، بر اثر سکته‌ی مغزی)"],
            ["تحصیلات", "لیسانس و کارشناسی ارشد: دانشگاه Manitoba؛ دکترای ادبیات انگلیسی: Trinity Hall, Cambridge (استاد راهنما: M.C. Bradbrook)"],
            ["همسر", "کورین لوئیس (Corinne Lewis) — از ۱۹۳۹، شش فرزند، از جمله اریک مک‌لوهان"],
            ["دین", "کاتولیک (تأثیر عمیق در آثار دیرهنگام و دین‌محور)"],
            ["استادداری", "۳۴ سال در دانشگاه تورنتو؛ بنیان‌گذار مرکز مطالعات رسانه‌ای"],
            ["جایزه", "نشان کانادا (Order of Canada, CC, 1970)"],
        ],
        col_widths=[4, 12],
    )

    D.h2("۲.۲. کودکی و خانواده: ادمونتون، آلبرتا")
    D.para("مک‌لوهان در ۲۱ ژوئیه ۱۹۱۱ در ادمونتون، در ایالت آلبرتای غرب کانادا، به دنیا آمد. پدرش، ارنست ویلیام مک‌لوهان، مهندس راه‌آهن بود و مادرش، فلورانس بریدگمن، از خانواده‌ای معیشت‌محور. زندگی خانواده به شدت به چرخه‌ی کار پدر وابسته بود؛ با پایان جنگ جهانی اول و رکود اقتصادی، خانواده درگیر ورشکستگی و جابه‌جایی‌های مکرر شد. این بی‌ثباتی اولیه، بعدها در فهم مک‌لوهان از «تأثیر فناوری بر ساختار زندگی» و حساسیتش به تغییرات محیطی، ردپا گذاشت.")
    D.para("مک‌لوهان به‌سختی در مدرسه دروس علمی پیش رفت؛ ضعفی که او را در دوران نوجوانی به‌سوی ادبیات و هنر سوق داد. همین «دورافتادن» از مسیر مهندسیِ پدر، در نهایت مسیر او را به سمت نقادیِ ادبی — نه مهندسی — باز کرد. بیوگراف‌ها (مارچاند، گوردون) تأکید دارند که این نقطه‌ی عطف، کلید فهم شخصیت اوست: مک‌لوهان تا اواخر عمر، خود را «ادیب و معلم» می‌دانست، نه «نظریه‌پرداز رسانه».")

    D.h2("۲.۳. وینیپگ و دانشگاه منیتوبا (۱۹۲۸–۱۹۳۳)")
    D.para("در ۱۹۲۸ وارد دانشگاه منیتوبا در وینیپگ شد. در ابتدا رشته‌ی مهندسی انتخاب کرد — در سایه‌ی شغلی پدر — اما به‌سرعت از آن دست کشید و به رشته‌ی هنر (Arts) و سپس زبان و ادبیات انگلیسی گذشت. در منیتوبا، مک‌لوهان برای اولین بار با روش‌های «خوانش نزدیک» (close reading) ادبیات آشنا شد؛ روشی که بعدا‌ً، به «تحلیل الگو» (pattern analysis) بدل شد و امضای روش‌شناختی او شد. همان‌جا نیز با آثار ادبا بزرگ انگلیسی و ایرلندی، از جمله جیمز جویس (James Joyce)، آشنا شد؛ آثاری که تا پایان عمر الهام‌بخش او ماندند.")

    D.h2("۲.۴. کمبریج: مدرسه‌ی نقد نو (۱۹۳۴–۱۹۳۶)")
    D.para("مک‌لوهان برای ادامه‌ی تحصیل به Trinity Hall در دانشگاه کمبریج رفت. این دورانی‌ای بود که او را شکل داد. در کمبریج با دو چهره‌ی کلیدی ادبیات مدرن — ای.آر. جی. ریچاردز (I.A. Richards) و دی.ژ. لیویس (D.J. Lewis) — مواجه شد. ریچاردز، بنیان‌گذار «نقد نو» (New Criticism)، به او آموخت که زبان، نه آینه‌ی باطن، بلکه ابزاری‌ای است که ادراک و فهم را می‌سازد. این ایده — «زبان و رسانه، ادراک را می‌سازند، نه آنکه صرفا‌ً بازتابش دهند» — ریشه‌ی مستقیم شعار «رسانه پیام است» است.")
    D.para("در کمبریج، رساله‌ی او بر ادبیات کلاسیک و مفهوم «سه‌گانه‌ی کلاسیک» (Classical Trivium: گرامر، شاعری، منطق) متمرکز بود؛ رسالهی‌ای که سال‌ها بعد (2006) به‌عنوان کتاب منتشر شد. این ریشه‌ی کلاسیک، توضیح می‌دهد چرا آثار مک‌لوهان پر از ارجاعات به یونان و روم باستان، و چرا او «تاریخ» را به‌شکل الگوهای تکرارشونده می‌خواند، نه به‌شکل رویدادهای خطی.")

    D.h2("۲.۵. سنت‌لوئیس و ازدواج (۱۹۳۶–۱۹۴۴)")
    D.para("پس از کمبریج، مک‌لوهان به دانشگاه سنت‌لوئیس در مینسوتا رفت و در آنجا ادبیات تدریس کرد. در همین دوران با کورین لوئیس ازدواج کرد (1939) و زندگی خانوادگی‌اش آغاز شد؛ از این پیوند شش فرزند به دنیا آمدند، از جمله اریک (Eric) که بعدا‌ً همکار و واریس فکری پدر شد. در سنت‌لوئیس، مک‌لوهان رساله‌ی دکترایش را تکمیل کرد و با شکسپیر و سنت ادبی انگلیسی عمیق‌تر درگیر شد. منابع نشان می‌دهند که او در این دوره هنوز یک «نقاد ادبی» بود و به فناوری و رسانه، به‌عنوان حوزه‌ی پژوهش، ورود نکرده بود.")

    D.h2("۲.۶. بازگشت به تورنتو و آشنایی با هارولد اینیس (۱۹۴۴ به بعد)")
    D.para("در ۱۹۴۴ (با برخی منابع ۱۹۴۶) به دانشگاه تورنتو بازگشت و تا پایان عمر (با یک دوره‌ی کوتاه در دانشگاه فوردهام ۱۹۶۷–۷۰) در آنجا استاد بود. نقطه‌ی عطف بزرگ این دوره، آشنایی با هارولد اینیس (Harold Innis) بود — اقتصاددان، تاریخ‌دان و نظریه‌پرداز ارتباطات اهل تورنتو، که مؤثرترین استاد و الهام‌بخش مک‌لوهان شد. اینیس، در کتاب‌هایش (Empire and Communications, 1950; The Bias of Communication, 1951)، مفهوم «سوگیری رسانه» (media bias) را ابداع کرده بود: هر رسانه، بسته به ماهیتش، یا «سوگیری در زمان» دارد یا «سوگیری در فضا». مک‌لوهان کتاب Bias of Communication را به‌عنوان «سند بنیان‌گذاری» خود می‌دانست و بسیاری از مفاهیمش را از اینیس گرفت و به سوی رسانه‌های الکترونیکی بسط داد. (بخوانید: فصل ۴ — زمینه‌ی فکری.)")

    D.h2("۲.۷. اوج شهرت: دهه‌ی ۱۹۶۰")
    D.para("دو کتاب — کهکشان گوتنبرگ (1962) و درک رسانه‌ها (1964) — مک‌لوهان را از یک استاد ادبیاتِ کم‌نام، به مشهورترین نظریه‌پرداز رسانه‌ای جهان تبدیل کرد. روزنامه‌ی San Francisco Chronicle او را «داغ‌ترین داراییِ دانشگاهیِ دوران» (the hottest academic property around) خواند. نام «مک‌لوهانیسم» (mucluhanism) وارد زبان فرانسوی شد؛ شرکت‌های بزرگ (جنرال‌موتورز، بل‌تلفون) به او پول پرداختند تا آینده‌ی محصولاتشان را پیش‌بینی کند؛ و نخست‌وزیر کانادا، پیر ترودو، ماهانه با او دیدار می‌کرد تا تصویر تلویزیونی‌اش را بهبود بخشد.")
    D.para("در ۱۹۶۷ به کرسی آلبرت شوتسه (Albert Schweitzer) در دانشگاه فوردهام نیویورک رفت — دوره‌ای‌ای که هم به اوج شهرتش و هم به تشخیص بیماری‌اش انجامید. در فوردهام، توموری خوش‌خیم در مغز او شناسایی شد؛ بیماری‌ای که در سال‌های پایانی بر توان فکری‌اش سایه انداخت. در ۱۹۷۰ نشان کانادا را دریافت کرد و در ۱۹۷۷ در فیلم آنی‌هال (Annie Hall) وودی آلن، در نقش خود ظاهر شد. او در ۳۱ دسامبر ۱۹۸۰، در تورنتو، درگذشت.")

    D.h2("۲.۸. شخصیت و سبک: چرا این‌گونه می‌نوشت؟")
    D.para("درک آثار مک‌لوهان بدون درک شخصیت و سبک او ممکن نیست. او مردی پرشور، متهور و «نیمه‌ی شاعر-نیمه‌ی پوپولیست» بود. سبک نوشتارش آکنده از پارادوکس، کلمه‌سازی (neologism)، ضرب‌المثل و ارجاعات ادبی بود. خودش درباره‌ی آثارش می‌گفت: «من ادعای فهمیدنشان را ندارم؛ کارم بسیار دشوار است» (I don't pretend to understand it. After all, my stuff is very difficult.) و روشش را به «کارِ دزدِ گاوصندوق» تشبیه می‌کرد: «نمی‌دانم داخلش چیست؛ شاید هیچ‌چیز نباشد. فقط می‌نشینم و شروع می‌کنم. می‌گرم، گوش می‌دهم، آزمایش می‌کنم، قبول و رد می‌کنم — تا آنکه پینون‌ها می‌افتند و درها باز می‌شوند.»")
    D.callout("کلید فهم:", "سبک مک‌لوهان «موزائیکی» است: پدیده‌ها مثل قطعات موزاییک در کنار هم چیده می‌شوند تا نگاه خواننده الگو را ببیند. او «تحلیل کمّی» و «مدل‌سازی» را نمی‌پذیرفت. این نکته را در فصل ۱۱ (نقد روش‌شناسی) با جزئیات می‌بینیم — چون دقیقا‌ً همین سبک، زمینه‌ساز بزرگ‌ترین انتقادها به او بوده است.")

    D.h2("۲.۹. دوران دیرهنگام و گرایش دینی")
    D.para("سال‌های پایانی زندگی مک‌لوهان (از اواسط دهه‌ی ۱۹۷۰ تا مرگ در 1980)، دوره‌ای «دین‌محور» بود. بیماری مغزی که در فوردهام (1967) تشخیص داده شد، بر توان فکری‌اش اثر گذاشت و او را به «مدیته‌ی» و «دین» نزدیک‌تر کرد. آثار دیرهنگامش — The New Millennium (1994) و The Medium and the Light (1992/2002) — پر از «بصیرت‌های دینی» و «تأملات» در «رابطه‌ی رسانه و ایمان» است. مک‌لوهان، «رسانه» را به «اسماعیل» و «کشف» تشبیه می‌کرد: رسانه، «بصیرت» را می‌سازد، و «بصیرت»، «مسیرِ دینی» است. این «گرایش دینی»، یکی از «وجه‌های نادیده‌شده» شخصیت اوست که در بیوگرافی‌ها (گوردون، مارچاند) با جزئیات پوشش داده شده است.")

    D.h2("۲.۱۰. مرگ و بازتاب آن")
    D.para("مک‌لوهان در ۳۱ دسامبر ۱۹۸۰، در تورنتو، بر اثر «سکته‌ی مغزی» درگذشت. مرگ او، «پایانِ» یک عصر را علامت‌گذاری کرد — عصری‌ای که در آن «رسانه» به «عنوانِ» یک حوزه‌ی پژوهش مستقل «به رسمیت» شناخته شد. اما «میراث» او، «مرگ» او را پشت سرگذاشت: در دهه‌ی ۱۹۹۰ و ۲۰۰۰، «بازگشت» مک‌لوهان به «عصر دیجیتال» آغاز شد و «نامش» دوباره در «سرخط‌های» رسانه‌ها ظاهر شد. امروز، «مک‌لوهان» نه تنها یک «نظریه‌پرداز» است، بلکه یک «نماد فرهنگی» است — نمادی‌ای که «تصویرِ ما از فناوری و فرهنگ» را شکل داده است.")
    D.page_break()
